import{_ as a,a as t,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 109 A good idea","description":"学习 much/many 的比较级，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 109 A good idea","description":"学习 much/many 的比较级，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 much/many 的比较级，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 108 How do they compare?","link":"/life/english/new-concept/book-1/unit-05/lesson-108"},"next":{"text":"第一册：英语初阶 · Lesson 110 How do they compare?","link":"/life/english/new-concept/book-1/unit-05/lesson-110"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 108 How do they compare?","link":"/life/english/new-concept/book-1/unit-05/lesson-108"},"next":{"text":"第一册：英语初阶 · Lesson 110 How do they compare?","link":"/life/english/new-concept/book-1/unit-05/lesson-110"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-109.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-109.md"}'),n={name:"life/english/new-concept/book-1/unit-05/lesson-109.md"};function l(i,e,r,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第一册-英语初阶-·-lesson-109-a-good-idea" tabindex="-1">第一册：英语初阶 · Lesson 109 A good idea <a class="header-anchor" href="#第一册-英语初阶-·-lesson-109-a-good-idea" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 109 A good idea&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-110">配套课 Lesson 110</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>比较数量并表达程度 本课要掌握much/many 的比较级，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>idea</td><td>/aɪˈdɪə/</td><td>n.</td><td>主意</td><td>a good idea</td></tr><tr><td>less</td><td>/les/</td><td>限定词</td><td>更少（不可数）</td><td>less sugar</td></tr><tr><td>fewer</td><td>/ˈfjuːə/</td><td>限定词</td><td>更少（可数复数）</td><td>fewer cups</td></tr><tr><td>more</td><td>/mɔː/</td><td>限定词</td><td>更多</td><td>more water</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>less sugar — 更少的糖</li><li>fewer cups — 更少的杯子</li></ul><h2 id="语法讲解-much-many-的比较级" tabindex="-1">语法讲解：much/many 的比较级 <a class="header-anchor" href="#语法讲解-much-many-的比较级" aria-label="Permalink to &quot;语法讲解：much/many 的比较级&quot;">​</a></h2><p>much 与 many 的比较级都是 more；little 表不可数数量时比较级为 less；few 对应 fewer，用于可数复数。比较水量用 more/less water，比较杯子数量用 more/fewer cups。a little 也可修饰比较级，表示稍微，如 a little cheaper。many 与 much 的选择取决于名词可数性，不能根据中文“多”判断。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>This recipe needs less sugar than the old one.</p></blockquote><p>这个配方需要的糖比旧配方少。</p><p>Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>标准书面表达中，cups 可数复数用 fewer；sugar 不可数用 less。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“This recipe needs less sugar than the old one.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>This recipe needs less sugar than the old one. We used fewer paper cups this week.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“比较数量并表达程度”写两至三句，再读给同伴听。至少使用一次much/many 的比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。 Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 less/fewer：___ sugar.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> less</p><p><strong>解析：</strong> 按本课规则判断：much 与 many 的比较级都是 more；little 表不可数数量时比较级为 less；few 对应 fewer，用于可数复数。比较水量用 more/less water，比较杯子数量用 more/fewer cups。a little 也可修饰比较级，表示稍微，如 a little cheaper。many 与 much 的选择取决于名词可数性，不能根据中文“多”判断。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这个配方需要的糖比旧配方少。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> This recipe needs less sugar than the old one.</p><p><strong>解析：</strong> Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：We used fewer paper cups this week.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 这周我们用了更少的纸杯。</p><p><strong>解析：</strong> Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：much/many 的比较级。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-108">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-110">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
